        {"kind":"code","file":"src/MessagePack.SourceGenerator/CodeAnalysis/TypeCollector.cs","line":1030,"rev":"head","quote":"if (isIntKey && intKey is not null)"},
        {"kind":"code","file":"src/MessagePack.SourceGenerator/CodeAnalysis/TypeCollector.cs","line":1046,"rev":"head","quote":"else if (!isIntKey && stringKey is not null)"},
        {"kind":"code","file":"src/MessagePack.SourceGenerator/CodeAnalysis/TypeCollector.cs","line":1065,"rev":"head","quote":"if (messagePackFormatter == null && collectMemberTypes)"},
        {"kind":"check","id":"tests.full_suite","status":"pass"},
        {"kind":"check","id":"tests.fail_without_fix","status":"pass"}
      ]
    },
    {
      "req": "REQ-2234-F2",
      "verdict": "cannot_determine",
      "confidence_basis": "The clause's named test (SourceGenerationOnlyDiagnosticsAreNotReportedWhenSuppressed) is not in facts.json; available tests pass but none isolates that source-generation-only diagnostics such as partial-class requirements are suppressed for SuppressSourceGeneration types, and the tail of GetObjectInfo where those requirements surface was not provided.",
      "evidence": [
        {"kind":"test","name":"MsgPack00xAnalyzerTests.SuppressSourceGeneration_ValidTypeHasNoDiagnostics","outcome":"passed"},
        {"kind":"code","file":"src/MessagePack.SourceGenerator/CodeAnalysis/TypeCollector.cs","line":1007,"rev":"head","quote":"if (suppressSourceGeneration is not true && isInitOnly)"}
      ]
    },
    {
      "req": "REQ-2234-N1",
